import { test, expect } from "@playwright/test";

const PRODUCTION_URL = "https://rockcap.vercel.app";

test.describe("Production Docs Page Verification", () => {
  test("docs page is accessible on production", async ({ page }) => {
    // Navigate directly to production docs page
    await page.goto(`${PRODUCTION_URL}/docs`);

    // Should either:
    // 1. Redirect to login (if not authenticated) - expected behavior
    // 2. Show docs content (if authenticated)

    // Wait for navigation to complete
    await page.waitForLoadState("domcontentloaded");

    // Check if we're on login page (expected for unauthenticated users)
    const currentUrl = page.url();
    const isLoginPage = currentUrl.includes("/login");

    if (isLoginPage) {
      // Verify login page loads correctly
      const loginForm = page.locator('input[placeholder*="Enter password"], input[type="password"]');
      await expect(loginForm).toBeVisible({ timeout: 5000 });

      // Verify redirect parameter is set correctly
      expect(currentUrl).toContain("redirect=%2Fdocs");

      console.log("✓ Docs page correctly redirects to login (expected behavior)");
    } else {
      // If we're on the docs page, verify it loads content
      await page.waitForTimeout(3000); // Wait for API calls

      // Check for error messages
      const errorElement = page.locator('text=/Error:/i');
      const hasError = await errorElement.isVisible().catch(() => false);

      if (hasError) {
        const errorText = await errorElement.textContent();
        throw new Error(`Docs page shows error: ${errorText}`);
      }

      // Verify page has content
      const body = page.locator('body');
      const bodyText = await body.textContent();
      expect(bodyText).toBeTruthy();
      expect(bodyText!.length).toBeGreaterThan(100);

      console.log("✓ Docs page loads content successfully");
    }
  });

  test("docs API endpoint is accessible on production", async ({ page }) => {
    // Navigate to production
    await page.goto(`${PRODUCTION_URL}/login`);

    // Try to access the docs manifest API
    // Note: This will likely return 401/403 if auth is required, which is expected
    const response = await page.request.get(`${PRODUCTION_URL}/api/docs/manifest`);

    // API should respond (even if with auth error)
    expect([200, 401, 403, 404]).toContain(response.status());

    if (response.status() === 200) {
      const data = await response.json();
      expect(data).toHaveProperty("docs");
      expect(Array.isArray(data.docs)).toBe(true);
      console.log(`✓ Docs API returns ${data.docs.length} documents`);
    } else {
      console.log(`✓ Docs API requires authentication (status: ${response.status()})`);
    }
  });

  test("production site is not returning 404 errors", async ({ page }) => {
    // Check that the production domain resolves correctly
    const response = await page.goto(`${PRODUCTION_URL}/`);

    // Should not be a 404
    expect(response?.status()).not.toBe(404);

    // Should redirect to login or show content
    await page.waitForLoadState("domcontentloaded");
    const currentUrl = page.url();

    // Should either be on login or home page
    expect(currentUrl).toMatch(/\/login|\/$/);

    console.log(`✓ Production root page loads correctly (${currentUrl})`);
  });
});

