import { test, expect } from "@playwright/test";

const PRODUCTION_URL = "https://rockcap.vercel.app";
const PASSWORD = "vK8#zQ1p@Lr3wTx9!";

test.describe("Production Docs Page Screenshot", () => {
  test("docs page loads and displays content after authentication", async ({ page }) => {
    // Navigate to production login page
    await page.goto(`${PRODUCTION_URL}/login`);

    // Wait for login form to be visible
    const passwordInput = page.locator('input[type="password"]');
    await expect(passwordInput).toBeVisible({ timeout: 10000 });

    // Fill in password
    await passwordInput.fill(PASSWORD);

    // Click login button
    await page.click('button:has-text("Login")');

    // Wait for navigation away from login page
    await page.waitForURL(/^(?!.*\/login)/, { timeout: 10000 });

    // Navigate to docs page
    await page.goto(`${PRODUCTION_URL}/docs`);

    // Wait for page to load
    await page.waitForLoadState("domcontentloaded");

    // Wait for API call to complete (docs manifest)
    await page.waitForTimeout(3000);

    // Verify page loaded successfully (not showing error)
    const errorElement = page.locator('text=/Error:/i');
    const hasError = await errorElement.isVisible().catch(() => false);

    if (hasError) {
      const errorText = await errorElement.textContent();
      throw new Error(`Docs page shows error: ${errorText}`);
    }

    // Verify we're on the docs page (check for search input or docs content)
    const searchInput = page.locator('input[placeholder*="Search"], input[placeholder*="search"]');
    const hasSearchInput = await searchInput.isVisible().catch(() => false);

    if (!hasSearchInput) {
      // Check if page has any content at all
      const body = page.locator('body');
      const bodyText = await body.textContent();
      if (!bodyText || bodyText.length < 100) {
        throw new Error("Docs page appears to be empty or not loaded");
      }
    }

    // Take screenshot
    await page.screenshot({
      path: "test-results/vercel-docs-production-working.png",
      fullPage: true,
    });

    console.log("✓ Screenshot saved to test-results/vercel-docs-production-working.png");

    // Verify URL is correct
    expect(page.url()).toContain("/docs");

    // Verify page has content
    const body = page.locator('body');
    const bodyText = await body.textContent();
    expect(bodyText).toBeTruthy();
    expect(bodyText!.length).toBeGreaterThan(100);
  });
});
